/* Тетрадь кампании v4 — листы курса «Кампания» v3. Где у листа есть сущность, графа `profile` показывает живые данные кампании;
   остальное — ответы в форме курса. Ключи постоянные: переименование графы потеряло бы ответы при обновлении. */
const note = (key:string,hint:string):F => ({key,label:"",type:"note",hint});
const heading = (key:string,label:string):F => ({key,label,type:"heading"});
const marks = (key:string,label:string,options:string[],hint?:string):F => ({key,label,type:"checklist",options,optional:true,...(hint?{hint}:{})});
/** Таблица курса с заданными строками: строка — вопрос, колонка — ответ. */
const rowsTable = (key:string,label:string,rows:[string,string][],hint?:string,columns:F[]=[line("value","Запись")],rowHeader=""):F =>
  ({key,label,type:"table",rowHeader,rows:rows.map(([key,label])=>({key,label})),columns,...(hint?{hint}:{})});
const lines = (key:string,label:string,columns:F[],minRows:number,hint?:string):F => ({...table(key,label,columns,hint),minRows});
const cards = (key:string,label:string,entity:string,fields:F[],hint?:string):F => ({...group(key,label,fields,hint),entity});
const view = (key:string,entity:string,label:string,hint:string):F => ({key,label,type:"profile",entity,hint});
const part = (number:string,part:string,s:WorkbookSheet):WorkbookSheet => ({...s,number,part});
const STATUS = choice("status","Статус",["У","П","Ч"]);
const KNOWN = choice("known","Кому известно",["М","Г","И","В"]);
const meeting = ref("session","Встреча","Профиль сессии; по нему названа карточка.");

